-- FASE D · Bloque 4 · Profetas menores 2: Jonás, Miqueas, Nahúm y Habacuc
update public.biblical_books
set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('coverage_status','context_ready'),updated_at=now()
where code in ('JON','MIC','NAM','HAB');

with source as (select id from public.biblical_sources where slug='vida-contexto-editorial'),
data(slug,book_code,scope_kind,chapter_start,chapter_end,title,summary,historical_context,jewish_context,literary_context,authorial_intent,theological_reflection,interpretive_cautions,key_terms,people_groups,places) as (
values
('jonas-perfil','JON','book',1,4,'Jonás: misericordia, enemigo y resistencia del profeta','Jonás narra cómo un profeta huye del llamado a anunciar a Nínive, es rescatado del mar, predica brevemente y se enoja cuando Dios muestra misericordia a la ciudad enemiga.','Nínive fue una ciudad asiria asociada con un imperio violento. El relato utiliza marineros, una gran ciudad, animales y una planta para examinar el nacionalismo religioso y la compasión.','Jonás se lee en Yom Kipur, cuando su llamado al retorno y la misericordia hacia Nínive acompañan la reflexión judía sobre arrepentimiento.','El libro es una narración profética satírica: personajes extranjeros responden mejor que el profeta y la historia termina con una pregunta de Dios sin respuesta.','Confrontar una espiritualidad que desea misericordia para sí misma pero juicio inmediato para el enemigo, y mostrar que la compasión divina supera fronteras.','Dios puede trabajar con una persona resistente y también cuidar a quienes esa persona preferiría excluir. El arrepentimiento auténtico puede aparecer en lugares inesperados.','El género y la historicidad exacta del relato son debatidos y deben presentarse honestamente. La gran criatura no es el centro del libro ni una prueba científica. La misión no autoriza acercarse de forma insegura a personas violentas.',ARRAY['Jonás','Nínive','misericordia','arrepentimiento','enemigo','gran pez']::text[],ARRAY['asirios','ninivitas','marineros','israelitas']::text[],ARRAY['Nínive','Jope','mar','Tarsis']::text[]),
('jonas-1-2-huida-rescate','JON','section',1,2,'Huida, tormenta y oración desde la profundidad','Jonás huye por mar, los marineros intentan salvar la embarcación y el profeta es rescatado por una gran criatura, desde donde pronuncia una oración de agradecimiento.','Los viajes marítimos implicaban gran riesgo y los marineros podían representar diversas religiones. Echar suertes era una práctica antigua de decisión, no una técnica recomendada.','Los marineros muestran temor, compasión y reverencia. La oración de Jonás reúne lenguaje de salmos y celebra rescate antes de que su actitud hacia Nínive haya cambiado.','Un descenso continuo —Jope, barco, fondo, mar— se invierte cuando Dios provee rescate. La ironía muestra que el profeta puede recitar gratitud y continuar necesitando transformación.','Mostrar que huir de responsabilidad afecta a otros y que el rescate divino ofrece una nueva oportunidad, no una aprobación automática del carácter.','La gracia puede encontrarnos en una profundidad creada también por nuestras decisiones. Ser rescatado es invitación a cambiar, no permiso para repetir el mismo patrón.','El relato no debe usarse para promover conductas peligrosas en el mar ni para afirmar que toda crisis es causada por desobediencia individual. Las suertes no constituyen método cristiano de discernimiento.',ARRAY['huida','tormenta','marineros','gran criatura','oración','rescate']::text[],ARRAY['Jonás','marineros']::text[],ARRAY['Jope','mar','Tarsis']::text[]),
('jonas-3-4-ninive','JON','section',3,4,'Nínive responde y el profeta se enoja','Jonás anuncia juicio, la ciudad responde con ayuno y cambio y Dios no ejecuta el desastre anunciado; el profeta protesta y recibe una lección mediante una planta y un viento.','Las descripciones de tamaño, rey y animales contribuyen al tono narrativo y no funcionan necesariamente como informe administrativo exacto de la capital asiria.','El arrepentimiento de Nínive se expresa en abandonar violencia, no solo en vestimenta o ayuno. El cierre incluye personas y animales dentro de la compasión divina.','La rapidez de la respuesta de Nínive contrasta con la lentitud del profeta. Una planta temporal revela que Jonás siente más por su comodidad que por una ciudad.','Preguntar si la comunidad de fe permitirá que Dios sea misericordioso con quienes considera enemigos y si su preocupación moral incluye vidas fuera de su grupo.','La compasión no significa negar la violencia de un imperio. Significa desear transformación antes que destrucción y reconocer el valor de personas que no controlamos.','El relato no minimiza la crueldad asiria ni exige confianza ingenua en un opresor. La misericordia de Dios no elimina la necesidad de cambio verificable y justicia.',ARRAY['Nínive','ayuno','violencia','planta','compasión','enemigo']::text[],ARRAY['ninivitas','asirios','Jonás']::text[],ARRAY['Nínive']::text[]),
('miqueas-perfil','MIC','book',1,7,'Miqueas: justicia, juicio y esperanza desde la periferia','Miqueas denuncia la corrupción de Samaria y Jerusalén, el despojo de tierras, profetas pagados y gobernantes violentos, y anuncia una futura paz, un gobernante de Belén y el perdón divino.','El profeta procede de Moreset, en la frontera rural de Judá, y ministra durante la expansión asiria y los reinados de Jotam, Acaz y Ezequías.','Miqueas 6:8 resume una ética de justicia, hesed y caminar humildemente. La promesa de Belén tiene horizonte davídico y recibió lectura mesiánica cristiana posterior.','Tres ciclos de juicio y esperanza se introducen con llamados a escuchar. Sion puede ser destruida y también transformada en centro de enseñanza y paz.','Confrontar a élites que usan ley y religión para apropiarse de tierra, y afirmar que la esperanza de liderazgo debe medirse por justicia y paz.','Caminar humildemente une vida interior y responsabilidad pública. Dios no busca espectáculo religioso que sustituya misericordia y justicia.','Miqueas 6:8 no debe reducirse a eslogan individual desconectado de despojo y tribunales. Miqueas 5:2 debe explicarse dentro de esperanza davídica antes de su uso cristiano.',ARRAY['Miqueas','justicia','hesed','Moreset','Belén','Sion','paz']::text[],ARRAY['campesinos','élites','profetas','Judá','Israel']::text[],ARRAY['Moreset','Samaria','Jerusalén','Belén']::text[]),
('miqueas-1-3-injusticia','MIC','section',1,3,'Caída de ciudades y liderazgo que despoja','Miqueas anuncia caída de Samaria, lamenta ciudades de Judá y acusa a quienes planifican apropiarse de casas y campos, a jueces corruptos y a profetas que adaptan mensajes al pago.','La presión asiria y la militarización podían intensificar deudas y concentración de tierra. Las aldeas de la Sefelá quedaban expuestas a invasiones.','La tierra familiar tenía significado económico y de pacto. Quitarla por fraude no era solamente negocio, sino ruptura de pertenencia comunitaria.','Juegos de palabras con nombres de ciudades conducen a acusaciones directas contra élites de Jerusalén y Sion.','Mostrar que la injusticia puede planificarse legalmente y que liderazgo religioso o político no queda protegido por su cargo.','La espiritualidad debe examinar quién pierde hogar, voz y seguridad para que otros prosperen. Decir la verdad no depende de quién financia el mensaje.','La metáfora intensa sobre líderes no debe describirse gráficamente ni leerse como invitación a violencia. La denuncia de profetas pagados no significa que todo ministro remunerado sea corrupto.',ARRAY['despojo','campos','jueces','profetas','Samaria','Sion']::text[],ARRAY['campesinos','jueces','profetas','élites']::text[],ARRAY['Samaria','Moreset','Jerusalén','Sefelá']::text[]),
('miqueas-4-7-esperanza-etica','MIC','section',4,7,'Paz de Sion, Belén y el camino de justicia','La visión transforma armas en herramientas agrícolas, anuncia reunión de personas vulnerables, espera un gobernante de Belén y culmina con un pleito del pacto, Miqueas 6:8 y una oración de perdón.','La guerra asiria hacía especialmente significativa una visión de seguridad bajo la propia vid y higuera. Belén recordaba el origen humilde de David.','La tradición judía conserva la esperanza de Sion y del gobernante davídico; la tradición cristiana relaciona Miqueas 5 con Jesús. El pleito del capítulo 6 recuerda éxodo y liderazgo de Moisés, Aarón y Miriam.','Poemas de futuro, imágenes de parto y pastor, un proceso judicial y una oración final unen esperanza pública y ética cotidiana.','Afirmar que la esperanza mesiánica produce paz, cuidado de quien cojea, justicia y humildad, no dominación religiosa.','La grandeza bíblica puede nacer de lugares pequeños. Caminar con Dios se expresa en decisiones justas y amor leal más que en sacrificios impresionantes.','«Harán arados de sus espadas» es una visión profética de paz y no una descripción de que toda amenaza ya terminó. La humildad no exige soportar abuso ni callar frente a injusticia.',ARRAY['Sion','paz','Belén','gobernante','Miqueas 6:8','perdón']::text[],ARRAY['vulnerables','Judá','naciones','líderes']::text[],ARRAY['Sion','Jerusalén','Belén']::text[]),
('nahum-perfil','NAM','book',1,3,'Nahúm: caída de Nínive y alivio de pueblos oprimidos','Nahúm anuncia la caída de Nínive y celebra el fin de un imperio conocido por conquista, propaganda y violencia, ofreciendo alivio a Judá después de décadas de presión asiria.','Nínive cayó en 612 a. C. ante babilonios y medos. Asiria había dominado la región mediante tributo, deportación y campañas militares.','El libro forma parte de los Doce y complementa a Jonás: la posibilidad de misericordia no elimina responsabilidad cuando un imperio vuelve a ejercer violencia.','Un himno inicial presenta justicia divina; después poemas de batalla y una sátira fúnebre describen el colapso de la capital imperial.','Dar voz al alivio de comunidades oprimidas y afirmar que el poder construido sobre terror no es eterno.','Es legítimo anhelar el fin de un sistema violento sin perder sensibilidad hacia las personas atrapadas dentro de él.','La poesía de guerra contiene imágenes intensas y no debe celebrarse de forma gráfica ni utilizarse para promover daño contra poblaciones modernas. Nínive antigua no equivale a una nación actual.',ARRAY['Nahúm','Nínive','Asiria','imperio','justicia','alivio']::text[],ARRAY['asirios','judíos','medos','babilonios']::text[],ARRAY['Nínive','Judá']::text[]),
('nahum-1-3-caida','NAM','section',1,3,'Justicia divina y caída de la ciudad imperial','El poema anuncia protección para quien busca refugio y fin para la opresión, luego presenta a Nínive sitiada, expuesta y convertida en ejemplo de un poder que no pudo sostenerse.','Las defensas urbanas, canales, carros y comercio de Nínive formaban parte de una capital imperial impresionante. Su caída sorprendió a la región.','El lenguaje de celos y venganza se refiere a justicia de pacto contra violencia persistente, no a impulsividad humana.','Un himno alfabético parcial abre hacia anuncios directos y una lamentación sarcástica que pregunta quién llorará a la ciudad.','Enseñar que la paciencia divina no significa indiferencia eterna frente al abuso y que el refugio de víctimas incluye límites al opresor.','Buscar justicia puede incluir celebrar que una estructura dañina terminó, pero debe evitar deshumanizar a personas.','La frase «Dios vengador» no autoriza venganza privada. La descripción de la ciudad no debe emplearse para justificar hostilidad étnica o nacional.',ARRAY['refugio','venganza divina','Nínive','sitio','imperio','caída']::text[],ARRAY['asirios','judíos','medos','babilonios']::text[],ARRAY['Nínive','Judá']::text[]),
('habacuc-perfil','HAB','book',1,3,'Habacuc: preguntas sobre violencia y fe perseverante','Habacuc dialoga con Dios sobre injusticia interna y sobre el uso de Babilonia como instrumento de juicio, recibe ayes contra el opresor y termina con una oración de confianza aun sin prosperidad visible.','El libro se sitúa probablemente durante el ascenso babilónico a finales del siglo VII a. C., cuando Judá enfrentaba violencia interna y amenaza imperial.','La frase «el justo por su fidelidad vivirá» se refiere a perseverancia dentro de crisis y fue retomada en interpretaciones judías y cristianas posteriores.','Dos quejas y respuestas abren el libro; una tabla visionaria y cinco ayes conducen a un salmo final con lenguaje teofánico.','Legitimar preguntas dirigidas a Dios, denunciar la lógica imperial y formar una fidelidad que no depende de resultados económicos inmediatos.','La fe no exige fingir que la violencia es comprensible. Puede esperar, protestar y decidir confiar sin tener todas las respuestas.','El libro no enseña que todo imperio violento sea enviado directamente por Dios de manera que quede moralmente aprobado. La fe de Habacuc no debe usarse para exigir optimismo o negar necesidades materiales.',ARRAY['Habacuc','violencia','Babilonia','justo','fidelidad','ayes','espera']::text[],ARRAY['judíos','babilonios','oprimidos']::text[],ARRAY['Judá','Babilonia']::text[]),
('habacuc-1-2-dialogo-ayes','HAB','section',1,2,'Quejas, respuesta y ayes contra el opresor','El profeta pregunta hasta cuándo tolerará Dios violencia, se sorprende al escuchar sobre Babilonia y espera una respuesta; luego una visión anuncia que el orgulloso no permanecerá y condena saqueo, deuda, explotación e idolatría.','Babilonia expandía su poder mediante conquista y tributo. La imagen del acreedor y de pueblos saqueados refleja economía imperial.','La espera en la torre simboliza vigilancia profética. La fidelidad del justo contrasta con la persona hinchada por poder y apetito.','Queja, respuesta inquietante, espera y cinco ayes construyen una discusión que no oculta la dificultad moral.','Mostrar que una respuesta parcial puede abrir nuevas preguntas y que el poder que Dios permite temporalmente continúa bajo evaluación moral.','Esperar no significa pasividad: incluye observar, escribir con claridad y negarse a aceptar la propaganda del vencedor.','«Escribe la visión» no es una fórmula para tableros de metas personales. «Aunque tarde» no garantiza que toda visión individual se cumplirá; se refiere al mensaje profético concreto.',ARRAY['hasta cuándo','torre','visión','justo','ayes','saqueo','idolatría']::text[],ARRAY['profeta','judíos','babilonios','naciones saqueadas']::text[],ARRAY['Judá','Babilonia']::text[]),
('habacuc-3-oracion','HAB','section',3,3,'Oración, memoria y gozo sin cosecha','El salmo final recuerda la acción divina mediante imágenes de éxodo y tormenta; el profeta tiembla ante lo que viene y decide alegrarse aun cuando campos y rebaños fallen.','La pérdida de cosechas y ganado significaba crisis económica y alimentaria real. El poema no minimiza esas consecuencias.','La oración usa lenguaje litúrgico y posiblemente indicaciones musicales. La memoria de antiguas liberaciones sostiene esperanza presente.','Una teofanía majestuosa se mueve hacia una confesión personal sobria, donde temblor y confianza permanecen juntos.','Presentar una fe que no depende de prosperidad y que puede sostenerse mediante memoria aun cuando el futuro es incierto.','El gozo no niega necesidad ni obliga a ocultar miedo. Es una orientación de confianza dentro de una situación que continúa siendo difícil.','El pasaje no debe utilizarse para negar ayuda material a quien perdió sustento ni para afirmar que pedir apoyo demuestra poca fe.',ARRAY['oración','teofanía','cosecha','temor','gozo','fuerza']::text[],ARRAY['campesinos','Judá','profeta']::text[],ARRAY['Judá','campos']::text[])
)
insert into public.biblical_context_units(slug,book_code,source_id,scope_kind,chapter_start,verse_start,chapter_end,verse_end,title,summary,historical_context,jewish_context,literary_context,authorial_intent,theological_reflection,interpretive_cautions,key_terms,people_groups,places,source_locator,provider_version,content_hash,review_status,enabled,metadata)
select data.slug,data.book_code,source.id,data.scope_kind,data.chapter_start,NULL,data.chapter_end,NULL,data.title,data.summary,data.historical_context,data.jewish_context,data.literary_context,data.authorial_intent,data.theological_reflection,data.interpretive_cautions,data.key_terms,data.people_groups,data.places,'vida://corpus/contexto/profetas-menores/v1#'||data.slug,'profetas-menores-v1-2026-08-02',encode(extensions.digest(concat_ws('|',data.slug,data.title,data.summary,data.historical_context,data.jewish_context,data.literary_context,data.authorial_intent,data.theological_reflection,data.interpretive_cautions),'sha256'),'hex'),'approved',true,jsonb_build_object('coverage_batch','minor-prophets','generated_by_ai',false,'review_level','editorial')
